with with_dims as (select a.id, a.order_id, a.quantity, d.channel, d.order_date from order_items a left join orders d on a.order_id = d.id) select case when quantity >= 8 then 'LARGE' else 'SMALL' end as quantity_tier, count(*) filter (where channel = 'partner') as partner_rows, bit_and(quantity) as quantity_bit_and, count(*) filter (where channel = 'partner') as partner_rows_2, count(*) as num_rows from with_dims group by quantity_tier having quantity_bit_and > 1
